const rows=(n)=>{try{return $items(n).map(x=>x.json||{}).filter(x=>Object.keys(x).length)}catch(e){return[]}};
// تقصير النصوص الطويلة: الواجهة تقرأ objective/next_action فقط، وكانت الاستجابة ٢٫٥ ميغا بسبب context وresult.
const URL_RE=/https?:\/\/\S+/g;
const cut=(v,n)=>{if(typeof v!=='string')return v;const s=v.replace(URL_RE,'[رابط]');return s.length>n?s.slice(0,n)+'…':s};
const DROP={tasks:['context'],agents:['system_prompt','prompt','instructions']};
const CAP={tasks:{objective:200,next_action:300,result:600,blocked_by:160,client_name:80},default:400};
const slim=(kind,list)=>list.map(r=>{const o={};for(const k of Object.keys(r)){if((DROP[kind]||[]).includes(k))continue;const cap=(CAP[kind]&&CAP[kind][k])||CAP.default;o[k]=cut(r[k],cap)}return o});
const out={
  ok:true,
  generated_at:new Date().toISOString(),
  agents:slim('agents',rows('Read Agents')),
  tasks:slim('tasks',rows('Read Tasks')),
  deals:slim('deals',rows('Read Deals')),
  kpis:slim('kpis',rows('Read KPIs')),
  campaigns:slim('campaigns',rows('Read Campaigns')),
  integrations:slim('integrations',rows('Read Integrations'))
};
out.payload_bytes=JSON.stringify(out).length;
return [{json:out}];

var REGION = 'eastus2';
var b = ($input.first().json || {}).body || {};
var t = String(b.text == null ? '' : b.text).trim();
if (!t) { throw new Error('لا يوجد نص لنطقه'); }
if (t.length > 900) { t = t.slice(0, 900); }
var esc = function (s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
var voice = /^[a-zA-Z-]+Neural$/.test(String(b.voice || '')) ? b.voice : 'ar-SA-ZariyahNeural';
var rate = /^[+-]?\d{1,2}%$/.test(String(b.rate || '')) ? b.rate : '+0%';
var pitch = /^[+-]?\d{1,2}%$/.test(String(b.pitch || '')) ? b.pitch : '+0%';
var xml = '<speak version="1.0" xmlns="http://www.w3.org/2001/10/synthesis" xml:lang="' + voice.slice(0, 5) + '"><voice name="' + voice + '"><prosody rate="' + rate + '" pitch="' + pitch + '">' + esc(t) + '</prosody></voice></speak>';
return [{ json: { ssml: xml, url: 'https://' + REGION + '.tts.speech.microsoft.com/cognitiveservices/v1', voice: voice } }];

var b = ($input.first().json || {}).body || {};
var b64 = String(b.audio_b64 == null ? '' : b.audio_b64);
var comma = b64.indexOf('base64,');
if (comma !== -1) { b64 = b64.slice(comma + 7); }
if (!b64) { throw new Error('لا يوجد صوت في الطلب'); }
var buf = Buffer.from(b64, 'base64');
if (buf.length < 800) { throw new Error('التسجيل قصير جداً'); }
if (buf.length > 20000000) { throw new Error('التسجيل أكبر من الحد'); }
var mime = String(b.mime || 'audio/webm');
var name = mime.indexOf('mpeg') !== -1 ? 'clip.mp3' : (mime.indexOf('wav') !== -1 ? 'clip.wav' : 'clip.webm');
var bin = await this.helpers.prepareBinaryData(buf, name, mime);
return [{ json: { bytes: buf.length, mime: mime }, binary: { audio: bin } }];
